import { defineProvider, presets } from "@shared/core";

/**
 * AnyAPI (getanyapi.com) - one marketplace API over social, search,
 * e-commerce, jobs, real-estate and enrichment data. Every SKU is one
 * synchronous `POST https://api.getanyapi.com/v1/run/{sku}` with the SKU's
 * normalized input as the JSON body, `Authorization: Bearer aa_live_...`.
 * AnyAPI routes each call to the cheapest healthy upstream source (a
 * "lane") and fails over to the next on error.
 *
 * The endpoints are GENERATED by `deno task anyapi:scaffold`: one per SKU
 * Monid sells, the body mirrored from AnyAPI's OpenAPI document, the rate
 * card from its public catalog.
 *
 * BILLING (design D26/D27). AnyAPI prices in US dollars per request: flat,
 * or linear (base + per result / audio minute / ASIN, capped at `maxUsd`),
 * plus opt-in addons. The pool is US dollars and each endpoint's model is
 * the `pricing.from` offer - the lane default routing serves at. Every
 * success reports what the call cost in `costUsd`, so the provider
 * `consolidate` claims it and strips it from the output: a failover to a
 * dearer lane, a `source` pick, `requireFields` or `preferLatencyUnderMs`
 * all settle at the real charge, the fold riding along as the cross-check.
 */
export default defineProvider({
    name: "anyapi",
    meta: {
        displayName: "AnyAPI",
        summary: "Social, search, e-commerce, jobs and enrichment data " +
            "through one API with automatic source failover.",
        description: "Normalized live data from Instagram, TikTok, " +
            "LinkedIn, X, YouTube, Reddit, Facebook, Threads, Google " +
            "Search and Maps, Amazon, eBay, GitHub, Glassdoor, Zillow and " +
            "more, plus clean Markdown from any web page - one schema per " +
            "SKU whichever upstream source serves it. AnyAPI routes each " +
            "call to the cheapest healthy source and fails over to the " +
            "next on error.",
        homepageUrl: "https://getanyapi.com",
        docsUrl: "https://getanyapi.com/docs",
        categories: ["web-extraction"],
        notes: [
            "Results come back as `{output: {found, data, reason?}, items}`; " +
            "a target that does not exist is a 200 with `found: false`, " +
            "not an error.",
            "The price is the default (cheapest) source's. `source`, " +
            "`requireFields` and `preferLatencyUnderMs` can route to a " +
            "dearer source, and a failover can charge up to the SKU's " +
            "failover maximum; the response's `costUsd` settles the bill.",
            "Lane ids for `source` and `ignoreSources` are each SKU's " +
            "`lanes[].source.id` in the keyless catalog at " +
            "https://api.getanyapi.com/catalog.",
            "Send only fields the schema declares; another SKU's `limit`, " +
            "`cursor` or `sort` is rejected as invalid input at no charge.",
            "Paginated SKUs return `nextCursor`; pass it back as `cursor` " +
            "(and the same `source`, if one was sent) for the next page.",
        ],
    },
    auth: { inject: presets.auth.bearer() },
    request: { baseUrl: "https://api.getanyapi.com" },
    timeouts: { requestMs: 120_000, runMs: 120_000 },
    usage: {
        credits: { default: { label: "US dollars" } },
        /** The vendor's OWN claim (design D27): `costUsd` is what this
         *  call was charged. Pluck it (read + strip, one motion); entry
         *  OMITTED when absent. A free miss reports 0, which prunes to an
         *  empty claim and the derived fold settles. */
        consolidate: ({ data, utils }) => {
            const { value, rest } = utils.json.pluck(data.output, "$.costUsd");
            return {
                credits: {
                    ...(typeof value === "number" ? { default: value } : {}),
                },
                output: rest,
            };
        },
    },
    output: {
        /** `resultId` re-reads the run through OUR key, so it is no handle
         *  for the caller; `provider` is always "AnyAPI". */
        fromResponse: ({ data, utils }) =>
            utils.json.pluck(
                utils.json.pluck(data.output, "$.resultId").rest,
                "$.provider",
            ).rest,
        /** AnyAPI errors are `{error, code?, requestId?, payment?}`. Vendor
         *  non-2xx is DATA - the engine zero-bills it. */
        fromError: ({ data, utils }) => {
            const message = utils.json.optionalGet(data.output, "$.error");
            const code = utils.json.optionalGet(data.output, "$.code");
            return {
                message: typeof message === "string" && message !== ""
                    ? message
                    : "AnyAPI error",
                ...(typeof code === "string" ? { code } : {}),
                raw: data.output,
            };
        },
    },
});
